// =========================================================================
// UNIVERSAL MERGE NODE FOR: AutoPentest, Guardian, Sirius, Vuls
// =========================================================================

// === 1. HELPER FUNCTIONS (ฟังก์ชันตัวช่วยจัด Format) ===
function safeText(value, fallback = "", maxLength = 1500) {
  return String(value ?? fallback).slice(0, maxLength);
}

function normalizeSeverity(value, cvss = null) {
  const sev = String(value || "").toUpperCase();
  if (["CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO"].includes(sev)) return sev;

  const score = Number(cvss);
  if (!Number.isNaN(score)) {
    if (score >= 9.0) return "CRITICAL";
    if (score >= 7.0) return "HIGH";
    if (score >= 4.0) return "MEDIUM";
    if (score > 0.0) return "LOW";
  }
  return "INFO"; // Default
}

function normalizeStatus(value) {
  const status = String(value || "OPEN").toUpperCase();
  if (["OPEN", "FAILED", "IGNORED", "CLOSED", "RESOLVED"].includes(status)) return status;
  return "OPEN";
}

function buildSummary(findings) {
  return {
    total: findings.length,
    returned: findings.length,
    critical: findings.filter(f => f.severity === "CRITICAL").length,
    high: findings.filter(f => f.severity === "HIGH").length,
    medium: findings.filter(f => f.severity === "MEDIUM").length,
    low: findings.filter(f => f.severity === "LOW").length,
    info: findings.filter(f => f.severity === "INFO").length
  };
}

// ฟังก์ชันสำหรับดึงข้อมูลจาก Node อื่นอย่างปลอดภัย (ป้องกัน n8n Error ข้าม Branch)
function getSafeNodeData(nodeName) {
  try {
    const node = $(nodeName);
    return node && node.first() ? node.first().json : null;
  } catch (e) {
    return null;
  }
}

// === 2. INITIALIZE VARIABLES (ตั้งค่าตัวแปรเริ่มต้น) ===
const inputJson = $input.first().json || {};
let formattedFindings = [];
let finalTarget = "N/A";
let finalToolName = "unknown-tool";
let finalStatus = "completed";
let finalMeta = {};
let finalSummary = {};

// พยายามดึงข้อมูล Webhook ตามโครงสร้างเดิม
const wh1 = getSafeNodeData("Webhook1"); // Vuls
const wh2 = getSafeNodeData("Webhook2"); // Guardian/Autopentest
const wh3 = getSafeNodeData("Webhook3"); // Sirius

// === 3. DETECT TOOL NAME (วิเคราะห์ว่าข้อมูลมาจากเครื่องมือไหน) ===
if (inputJson.toolName) finalToolName = inputJson.toolName.toLowerCase();
else if (wh2 && wh2.body && wh2.body.toolName) finalToolName = wh2.body.toolName.toLowerCase(); 
else if (wh3 && wh3.body && wh3.body.toolName) finalToolName = "sirius";
else if (wh1 && wh1.body && wh1.body.toolName) finalToolName = "vuls";
// Fallbacks
if (finalToolName.includes("guardian")) finalToolName = "guardian";
if (finalToolName.includes("autopentest")) finalToolName = "autopentest";
if (inputJson.stdout && finalToolName === "unknown-tool") finalToolName = "guardian"; 

// === 4. PROCESS BY TOOL (แยกการทำงานตามเครื่องมือ) ===
try {
  // ---------------------------------------------------------
  // [A] AUTOPENTEST & GUARDIAN
  // ---------------------------------------------------------
  if (finalToolName === "guardian" || finalToolName === "autopentest") {
    const rawStdout = inputJson.stdout ? inputJson.stdout.trim() : "";
    finalTarget = (wh2 && wh2.body && wh2.body.target) ? wh2.body.target : "Unknown Target";
    finalToolName = (wh2 && wh2.body && wh2.body.toolName) ? wh2.body.toolName : finalToolName;

    if (rawStdout) {
      const rawData = JSON.parse(rawStdout);
      const sourceFindings = rawData.vulnerabilities || rawData.findings;

      // กรณีที่ 1: มี Findings ปกติ
      if (sourceFindings && Array.isArray(sourceFindings) && sourceFindings.length > 0) {
        sourceFindings.forEach(vuln => {
          formattedFindings.push({
            title: safeText(vuln.title || vuln.name, "Unknown Vulnerability", 200),
            severity: normalizeSeverity(vuln.severity),
            description: safeText(vuln.description, "No description provided."),
            remediation: safeText(vuln.remediation || vuln.solution, "Review findings and apply patches."),
            target: finalTarget,
            status: "OPEN",
            tool: finalToolName
          });
        });
      } 
      // กรณีที่ 2: Findings ว่างเปล่า แต่ AI เขียนสรุปมาให้
      else if (rawData.ai_decisions && Array.isArray(rawData.ai_decisions) && rawData.ai_decisions.length > 0) {
        let combinedAiReport = "";
        rawData.ai_decisions.forEach(decision => {
          if (decision.decision) combinedAiReport += decision.decision + "\n\n";
        });
        formattedFindings.push({
          title: "Guardian AI Security Assessment Report",
          severity: "HIGH",
          description: "AI Generated Report:\n" + safeText(combinedAiReport, "", 3000),
          remediation: "Please review the detailed AI text in the description for specific remediation steps.",
          target: finalTarget,
          status: "OPEN",
          tool: finalToolName
        });
      }
    }
  }

  // ---------------------------------------------------------
  // [B] SIRIUS
  // ---------------------------------------------------------
  else if (finalToolName === "sirius") {
    const hostReq = getSafeNodeData("HTTP Request7") || inputJson;
    const webhookBody = (wh3 && wh3.body) ? wh3.body : {};

    finalTarget = hostReq.ip || webhookBody.target || (webhookBody.parameters && webhookBody.parameters.target_ip) || "N/A";
    const vulnerabilities = Array.isArray(hostReq.vulnerabilities) ? hostReq.vulnerabilities : [];

    vulnerabilities.forEach((vuln, index) => {
      const riskScore = vuln.riskScore ?? vuln.risk_score ?? vuln.cvss ?? vuln.cvssScore ?? null;
      formattedFindings.push({
        title: safeText(vuln.title || vuln.name || vuln.vid, `Sirius Finding ${index + 1}`, 200),
        severity: normalizeSeverity(null, riskScore),
        description: safeText(vuln.description, "No description provided."),
        remediation: safeText(vuln.remediation || vuln.solution, "Review Sirius finding and apply recommended patches."),
        target: finalTarget,
        status: "OPEN",
        cvss: riskScore !== null ? Number(riskScore) : null,
        tool: "sirius",
        evidence: {
          source: "sirius",
          host_ip: hostReq.ip,
          hostname: hostReq.hostname,
          os: hostReq.os,
          osversion: hostReq.osversion,
          ports: hostReq.ports || [],
          vulnerability: vuln
        },
        raw: vuln
      });
    });
  }

  // ---------------------------------------------------------
  // [C] VULS
  // ---------------------------------------------------------
  else if (finalToolName === "vuls") {
    const webhookBody = (wh1 && wh1.body) ? wh1.body : {};
    const prepared = getSafeNodeData("Prepare Vuls Payload") || {};

    finalTarget = inputJson.target || prepared.target || webhookBody.target || (webhookBody.parameters && webhookBody.parameters.target_ip) || "N/A";
    const scanJobId = (inputJson.meta && inputJson.meta.scanJobId) || prepared.scanJobId || webhookBody.scanJobId || null;

    let vulsFindings = Array.isArray(inputJson.findings) ? inputJson.findings : [];

    vulsFindings.forEach(finding => {
       formattedFindings.push({
         title: safeText(finding.title, "Unknown Finding", 200),
         severity: normalizeSeverity(finding.severity, finding.cvss),
         description: safeText(finding.description, "Vuls detected a vulnerability on the target host.", 1500),
         remediation: safeText(finding.remediation, "Review affected packages and apply vendor security updates.", 1000),
         target: safeText(finding.target, finalTarget, 200),
         status: normalizeStatus(finding.status),
         cvss: finding.cvss !== undefined && finding.cvss !== null && !Number.isNaN(Number(finding.cvss)) ? Number(finding.cvss) : null,
         tool: "vuls"
       });
    });

    if (formattedFindings.length === 0) {
      formattedFindings.push({
        title: "VULS Scan Completed",
        severity: "INFO",
        description: "Vuls completed successfully, but no vulnerabilities were found or no CVE entries were parsed from the report.",
        remediation: "Check whether vulnerability databases are available, whether the target OS is supported, and whether packages were detected.",
        target: finalTarget,
        status: "OPEN",
        cvss: null,
        tool: "vuls"
      });
    }

    const hasFailedFinding = formattedFindings.some(f => f.status === "FAILED");
    finalStatus = (inputJson.status === "failed" || hasFailedFinding) ? "failed" : "completed";

    finalMeta = {
      tool: "vuls",
      target: finalTarget,
      serverLabel: (inputJson.meta && inputJson.meta.serverLabel) || prepared.serverLabel || null,
      scanJobId: scanJobId,
      exitCode: (inputJson.meta && inputJson.meta.exitCode !== undefined) ? inputJson.meta.exitCode : null
    };
    finalSummary = inputJson.summary || buildSummary(formattedFindings);
  }

} catch (error) {
  // ---------------------------------------------------------
  // [D] ERROR HANDLING (รองรับกรณีข้อมูลผิดพลาด)
  // ---------------------------------------------------------
  formattedFindings = [{
     title: "Data Parsing Error",
     severity: "INFO",
     description: "Failed to parse data for tool " + finalToolName + ". Error: " + error.message,
     remediation: "Check n8n Code node and raw tool output.",
     target: finalTarget,
     status: "IGNORED",
     tool: finalToolName
  }];
  finalStatus = "failed";
}

// === 5. FINAL PAYLOAD CONSTRUCTION ===
// สร้าง Summary ทิ้งท้ายให้ครบถ้วนก่อนส่งให้ Next.js
if (Object.keys(finalSummary).length === 0) {
    finalSummary = buildSummary(formattedFindings);
}

const payload = {
  toolName: finalToolName,
  target: finalTarget,
  status: finalStatus,
  summary: finalSummary,
  findings: formattedFindings,
  meta: finalMeta
};

// คืนค่าออกไปให้ n8n นำไปใช้ต่อ
return [{ json: payload }];

const body = $("Webhook1").first().json.body || {};
const params = body.parameters || {};

// รับค่าจากหน้าเว็บ
const targetIp =
  params.target_ip ||
  body.target ||
  body.parameters?.target ||
  "";

const sshUser = params.ssh_user || "";
const sshPort = Number(params.ssh_port || 22);

// สร้างชื่อ server สำหรับ config.toml
const serverLabel =
  params.server_label ||
  `target_${targetIp.replaceAll(".", "_").replaceAll("-", "_")}`;

// ใช้ private key กลางของระบบเสมอ
// ไม่ต้องรับ ssh_private_key จาก user
const authMethod = "private_key";

// path นี้คือ path ภายใน Vuls Docker container
// ต้องตรงกับตอน docker run ที่ mount .ssh เข้า /root/.ssh
const sshKeyPath = "/root/.ssh/id_rsa";

const sudoRequired = Boolean(params.sudo_required);
const legacySsh = Boolean(params.legacy_ssh);

if (!targetIp) {
  throw new Error("Missing target_ip for VULS");
}

if (!sshUser) {
  throw new Error("Missing ssh_user for VULS");
}

return [
  {
    json: {
      scanJobId: body.scanJobId,
      toolName: "vuls",

      target: targetIp,
      serverLabel,

      sshUser,
      sshPort,

      // backend/n8n จะใช้ key กลาง ไม่ใช่ key จาก user
      authMethod,
      sshKeyPath,

      sudoRequired,
      legacySsh
    }
  }
];

