  python3 - "$REPORT_FILE" <<'PY'
import json
import re
import sys

report_file = sys.argv[1]

with open(report_file, "r", encoding="utf-8", errors="ignore") as f:
    data = json.load(f)


def to_float(value):
    try:
        if value is None:
            return None

        if isinstance(value, (int, float)):
            n = float(value)
            return n if 0 <= n <= 10 else None

        if isinstance(value, str):
            value = value.strip()

            # CVSS vector ไม่ใช่ score เช่น CVSS:3.1/AV:N/...
            if value.startswith("CVSS:"):
                return None

            n = float(value)
            return n if 0 <= n <= 10 else None

        return None
    except Exception:
        return None


def normalize_severity(value):
    sev = str(value or "").upper().strip()

    if sev == "CRITICAL":
        return "CRITICAL"
    if sev in ["HIGH", "IMPORTANT"]:
        return "HIGH"
    if sev in ["MEDIUM", "MODERATE"]:
        return "MEDIUM"
    if sev in ["LOW", "NEGLIGIBLE"]:
        return "LOW"
    if sev in ["INFO", "INFORMATIONAL", "UNKNOWN", "NONE"]:
        return None

    return None


def severity_rank(sev):
    return {
        "CRITICAL": 4,
        "HIGH": 3,
        "MEDIUM": 2,
        "LOW": 1
    }.get(sev, 0)


def severity_from_score(score):
    n = to_float(score)

    if n is None:
        return "LOW"

    if n >= 9.0:
        return "CRITICAL"
    if n >= 7.0:
        return "HIGH"
    if n >= 4.0:
        return "MEDIUM"
    if n > 0.0:
        return "LOW"

    return "LOW"


def walk(obj):
    if isinstance(obj, dict):
        yield obj
        for value in obj.values():
            yield from walk(value)

    elif isinstance(obj, list):
        for item in obj:
            yield from walk(item)


def pick_score(cve):
    """
    ใช้เฉพาะ field ที่เป็น CVSS score จริง ๆ
    ไม่ใช้ key กว้าง ๆ อย่าง value เฉย ๆ เพราะทำให้ severity เพี้ยน
    """
    if not isinstance(cve, dict):
        return None

    scores = []

    trusted_score_keys = {
        "cvss3score",
        "cvss2score",
        "cvssscore",
        "maxcvssscore",
        "maxcvss3score",
        "maxcvss2score",
        "basescore",
        "base_score"
    }

    preferred_top_level = [
        "maxCvssScore",
        "maxCvss3Score",
        "maxCvss2Score",
        "cvss3Score",
        "cvss2Score",
        "cvssScore"
    ]

    # 1) top-level ก่อน
    for key in preferred_top_level:
        n = to_float(cve.get(key))
        if n is not None:
            scores.append(n)

    # 2) เดิน object หาเฉพาะ key ที่ชัดว่าเป็น CVSS score
    for obj in walk(cve):
        if not isinstance(obj, dict):
            continue

        for key, value in obj.items():
            key_l = str(key).lower()

            if key_l in trusted_score_keys:
                n = to_float(value)
                if n is not None:
                    scores.append(n)

    # 3) อ่าน score จาก structure ที่มักเจอใน CVSS metrics
    for obj in walk(cve):
        if not isinstance(obj, dict):
            continue

        # เช่น {"cvssData": {"baseScore": 8.8}}
        cvss_data = obj.get("cvssData") or obj.get("cvss_data")
        if isinstance(cvss_data, dict):
            n = to_float(cvss_data.get("baseScore") or cvss_data.get("base_score"))
            if n is not None:
                scores.append(n)

    if not scores:
        return None

    # เลือกคะแนนสูงสุดจาก CVSS score ที่เชื่อถือได้
    return max(scores)


def pick_severity(cve, score):
    """
    ให้ score เป็นตัวหลัก เพราะ Vuls summary อิง CVSS score เป็นหลัก
    ใช้ severity string เฉพาะกรณีไม่มี score เท่านั้น
    """
    if score is not None:
        return severity_from_score(score)

    severities = []

    if isinstance(cve, dict):
        for obj in walk(cve):
            if not isinstance(obj, dict):
                continue

            for key, value in obj.items():
                key_l = str(key).lower()

                # อ่านเฉพาะ field ที่เป็น severity จริง ๆ
                if key_l in [
                    "severity",
                    "cvss3severity",
                    "cvss2severity",
                    "threatseverity"
                ] or key_l.endswith("severity"):
                    sev = normalize_severity(value)
                    if sev:
                        severities.append(sev)

    if severities:
        return sorted(severities, key=severity_rank, reverse=True)[0]

    return "LOW"


def pick_summary(cve):
    if not isinstance(cve, dict):
        return "Vuls detected a vulnerability on the target host."

    preferred_keys = ["summary", "description", "title"]

    for obj in walk(cve):
        if not isinstance(obj, dict):
            continue

        for key in preferred_keys:
            if obj.get(key):
                return str(obj.get(key))[:1500]

    return "Vuls detected a vulnerability on the target host."


def iter_servers(obj):
    if isinstance(obj, list):
        for i, item in enumerate(obj):
            if isinstance(item, dict):
                yield item.get("serverName") or item.get("server_name") or f"server_{i}", item
        return

    if isinstance(obj, dict):
        if any(k in obj for k in ["scannedCves", "cves", "vulnerabilities"]):
            yield obj.get("serverName") or obj.get("server_name") or "target", obj
            return

        for name, value in obj.items():
            if isinstance(value, dict):
                value = dict(value)
                value.setdefault("serverName", name)
                yield name, value


findings = []

for server_name, server in iter_servers(data):
    target = (
        server.get("ip")
        or server.get("host")
        or server.get("serverName")
        or server_name
    )

    scanned = (
        server.get("scannedCves")
        or server.get("cves")
        or server.get("vulnerabilities")
        or {}
    )

    if isinstance(scanned, list):
        items = []
        for cve in scanned:
            if isinstance(cve, dict):
                cve_id = (
                    cve.get("cveID")
                    or cve.get("cveId")
                    or cve.get("vid")
                    or cve.get("id")
                    or cve.get("title")
                    or "Unknown CVE"
                )
                items.append((cve_id, cve))

    elif isinstance(scanned, dict):
        items = list(scanned.items())

    else:
        items = []

    for cve_id, cve in items:
        if not isinstance(cve, dict):
            cve = {}

        score = pick_score(cve)
        severity = pick_severity(cve, score)

        findings.append({
            "title": str(cve_id)[:200],
            "severity": severity,
            "description": pick_summary(cve),
            "remediation": str(
                cve.get("remediation")
                or cve.get("solution")
                or "Review affected packages and apply vendor security updates."
            )[:1000],
            "target": str(target)[:200],
            "status": "OPEN",
            "cvss": float(score) if score is not None else 0,
            "tool": "vuls"
        })


if not findings:
    findings.append({
        "title": "VULS Scan Completed",
        "severity": "LOW",
        "description": "Vuls completed successfully, but no CVE entries were parsed from the report.",
        "remediation": "Check whether vulnerability databases are available, whether the target OS is supported, and whether packages were detected.",
        "target": "{{ $json.target }}",
        "status": "OPEN",
        "cvss": 0,
        "tool": "vuls"
    })


summary = {
    "total": len(findings),
    "returned": len(findings),
    "critical": sum(1 for f in findings if f["severity"] == "CRITICAL"),
    "high": sum(1 for f in findings if f["severity"] == "HIGH"),
    "medium": sum(1 for f in findings if f["severity"] == "MEDIUM"),
    "low": sum(1 for f in findings if f["severity"] == "LOW"),
    "info": sum(1 for f in findings if f["severity"] == "INFO")
}

payload = {
    "toolName": "vuls",
    "target": "{{ $json.target }}",
    "status": "completed",
    "findings": findings,
    "summary": summary,
    "meta": {
        "tool": "vuls",
        "serverLabel": "{{ $json.serverLabel }}",
        "scanJobId": "{{ $json.scanJobId }}",
        "reportFile": report_file
    }
}

print(json.dumps(payload, ensure_ascii=False))
PY
fi

echo "###VULS_JSON_END###"

