const input = $input.first().json || {};

const webhookBody = $("Webhook1").first().json.body || {};
const prepared = $("Prepare Vuls Payload").first().json || {};

const target =
  input.target ||
  prepared.target ||
  webhookBody.target ||
  webhookBody.parameters?.target_ip ||
  "N/A";

const scanJobId =
  input.meta?.scanJobId ||
  prepared.scanJobId ||
  webhookBody.scanJobId ||
  null;

function safeText(value, fallback = "", maxLength = 1500) {
  return String(value ?? fallback).slice(0, maxLength);
}

function toNumber(value) {
  if (value === null || value === undefined || value === "") return null;

  const n = Number(value);
  return Number.isNaN(n) ? null : n;
}

function severityFromScore(score) {
  const n = toNumber(score);

  if (n === null) return "INFO";
  if (n >= 9.0) return "CRITICAL";
  if (n >= 7.0) return "HIGH";
  if (n >= 4.0) return "MEDIUM";
  if (n > 0.0) return "LOW";

  return "INFO";
}

function normalizeSeverity(value, cvss = null) {
  const sev = String(value || "").toUpperCase().trim();

  if (sev === "CRITICAL") return "CRITICAL";
  if (sev === "HIGH" || sev === "IMPORTANT") return "HIGH";
  if (sev === "MEDIUM" || sev === "MODERATE") return "MEDIUM";
  if (sev === "LOW" || sev === "NEGLIGIBLE") return "LOW";
  if (sev === "INFO" || sev === "INFORMATIONAL") return severityFromScore(cvss);

  return severityFromScore(cvss);
}

function normalizeStatus(value) {
  const status = String(value || "OPEN").toUpperCase();

  if (["OPEN", "FAILED", "IGNORED", "CLOSED", "RESOLVED"].includes(status)) {
    return status;
  }

  return "OPEN";
}

function extractJsonBlockFromStdout(stdout) {
  if (!stdout || typeof stdout !== "string") return null;

  const startMarker = "###VULS_JSON_START###";
  const endMarker = "###VULS_JSON_END###";

  const start = stdout.indexOf(startMarker);
  const end = stdout.indexOf(endMarker);

  if (start >= 0 && end > start) {
    const jsonText = stdout.slice(start + startMarker.length, end).trim();

    if (!jsonText) return null;

    try {
      return JSON.parse(jsonText);
    } catch (error) {
      return {
        toolName: "vuls",
        target,
        status: "completed",
        findings: [
          {
            title: "VULS JSON Parsing Error",
            severity: "INFO",
            description:
              "Vuls output contained a JSON marker, but the JSON block could not be parsed. Error: " +
              error.message,
            remediation:
              "Check the Execute Command node output between ###VULS_JSON_START### and ###VULS_JSON_END###.",
            target,
            status: "IGNORED",
            cvss: null,
            tool: "vuls"
          }
        ],
        summary: null,
        meta: {}
      };
    }
  }

  return null;
}

function normalizeFinding(finding) {
  const cvss = toNumber(finding.cvss);
  const severity = normalizeSeverity(finding.severity, cvss);

  return {
    title: safeText(finding.title, "Unknown Finding", 200),
    severity,
    description: safeText(
      finding.description,
      "Vuls detected a vulnerability on the target host.",
      1500
    ),
    remediation: safeText(
      finding.remediation,
      "Review affected packages and apply vendor security updates.",
      1000
    ),
    target: safeText(finding.target, target, 200),
    status: normalizeStatus(finding.status),
    cvss,
    tool: "vuls"
  };
}

function buildSummary(findings) {
  return {
    total: findings.length,
    returned: findings.length,
    critical: findings.filter(f => f.severity === "CRITICAL").length,
    high: findings.filter(f => f.severity === "HIGH").length,
    medium: findings.filter(f => f.severity === "MEDIUM").length,
    low: findings.filter(f => f.severity === "LOW").length,
    info: findings.filter(f => f.severity === "INFO").length
  };
}

// รองรับทั้ง input ที่เป็น payload แล้ว และ input ที่เป็น stdout จาก Execute Command
const parsedPayload = extractJsonBlockFromStdout(input.stdout || "");
const source = parsedPayload || input;

let findings = Array.isArray(source.findings) ? source.findings : [];

findings = findings.map(normalizeFinding);

if (findings.length === 0) {
  findings = [
    normalizeFinding({
      title: "VULS Scan Completed",
      severity: "INFO",
      description:
        "Vuls completed successfully, but no vulnerabilities were found or no CVE entries were parsed from the report.",
      remediation:
        "Check whether vulnerability databases are available, whether the target OS is supported, and whether packages were detected.",
      target,
      status: "OPEN",
      cvss: null,
      tool: "vuls"
    })
  ];
}

const hasFailedFinding = findings.some(f => f.status === "FAILED");

const status =
  source.status === "failed" || hasFailedFinding
    ? "failed"
    : "completed";

const summary = buildSummary(findings);

const payload = {
  toolName: "vuls",
  target: source.target || target,
  status,
  findings,
  summary,
  meta: {
    tool: "vuls",
    target: source.target || target,
    serverLabel:
      source.meta?.serverLabel ||
      prepared.serverLabel ||
      null,
    scanJobId:
      source.meta?.scanJobId ||
      scanJobId,
    exitCode:
      source.meta?.exitCode !== undefined
        ? source.meta.exitCode
        : input.code ?? null
  }
};

return [
  {
    json: payload
  }
];
